    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, cells))
    return out


def transform(grid):
    """Recolor the object nearest the dominant border-reaching bent marker."""
    objs = components(grid)
    h, w = len(grid), len(grid[0])
    candidates = []
    for color, cells in objs:
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        height, width = max(rs)-min(rs)+1, max(cs)-min(cs)+1
        touches_border = any(r in (0, h-1) or c in (0, w-1) for r, c in cells)
        # A large bent ray attached to an edge is the task's color key.
        if touches_border and len(cells) >= 8 and (height >= 4 or width >= 4):
            candidates.append((len(cells), color, cells))
    if not candidates:
        return [row[:] for row in grid]
    _, key_color, marker = max(candidates)
    targets = [(color, cells) for color, cells in objs if color != key_color]
    if not targets:
        return [row[:] for row in grid]
    # Minimum Manhattan gap between distinct components; deterministic tie-break by larger object.
    def gap(cells):
        return min(abs(r-y) + abs(c-x) for r, c in marker for y, x in cells)
    color, chosen = min(targets, key=lambda item: (gap(item[1]), -len(item[1])))
    out = [row[:] for row in grid]
    for r, c in chosen:
        out[r][c] = key_color
    return out


