from collections import Counter


def components(grid):
    h, w = len(grid), len(grid[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            seen.add((r, c))
            q, cells = deque([(r, c)]), []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, cells))
    return out


def transform(grid):
    """A two-edge L ray selects the closest object in its open quadrant for recoloring."""
    h, w = len(grid), len(grid[0])
    objs = components(grid)
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    guides = []
    for color, cells in objs:
        if color == background:
            continue
        sides = set()
        for r, c in cells:
            if r == 0: sides.add('top')
            if r == h-1: sides.add('bottom')
            if c == 0: sides.add('left')
            if c == w-1: sides.add('right')
        if len(sides) >= 2 and len(cells) >= 5:
            guides.append((len(cells), color, cells, sides))
    if not guides:
        return [row[:] for row in grid]
    _, key, guide, sides = max(guides)
    # The open quadrant lies opposite the pair of border rays.
    vertical_sign = -1 if 'bottom' in sides else 1 if 'top' in sides else 0
    horizontal_sign = -1 if 'right' in sides else 1 if 'left' in sides else 0
    # For a standard L, use its elbow determined by the extrema of the guide.
    rs = [r for r,c in guide]
    cs = [c for r,c in guide]
    r0 = min(rs) if 'top' in sides else max(rs) if 'bottom' in sides else (min(rs)+max(rs))//2
    c0 = min(cs) if 'left' in sides else max(cs) if 'right' in sides else (min(cs)+max(cs))//2
    candidates = []
    for color, cells in objs:
        if color == key or color == background:
            continue
        # Candidate must lie in the open quadrant diagonally opposite the L's arms.
        if vertical_sign and horizontal_sign:
            if not all((r-r0)*vertical_sign > 0 and (c-c0)*horizontal_sign > 0 for r,c in cells):
                continue
        # Near the elbow, with larger targets winning distance ties.
        distance = min(abs(r-r0)+abs(c-c0) for r,c in cells)
        candidates.append((distance, -len(cells), color, cells))
    if not candidates:
        return [row[:] for row in grid]
    _, _, _, target = min(candidates)
    out = [row[:] for row in grid]
    for r,c in target:
        out[r][c] = key
    return out


