{"output": "from collections import deque, Counter


def components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if (r,c) in seen: continue
            color=grid[r][c]; seen.add((r,c)); q=deque([(r,c)]); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((color,cells))
    return out


def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    objs=components(grid); guides=[]
    for color,cells in objs:
        if color==bg: continue
        sides=set()
        for r,c in cells:
            if r==0:sides.add('top')
            if r==h-1:sides.add('bottom')
            if c==0:sides.add('left')
            if c==w-1:sides.add('right')
        if len(sides)>=2:guides.append((len(cells),color,cells,sides))
    if not guides:return [row[:] for row in grid]
    _,key,guide,sides=max(guides)
    rs=[r for r,c in guide]; cs=[c for r,c in guide]
    # Recolor the closest object lying inward from the L's border corner.
    er=max(rs) if 'top' in sides else min(rs) if 'bottom' in sides else (min(rs)+max(rs))//2
    ec=max(cs) if 'left' in sides else min(cs) if 'right' in sides else (min(cs)+max(cs))//2
    dr=1 if 'top' in sides else -1
    dc=1 if 'left' in sides else -1
    candidates=[]
    for color,cells in objs:
        if color in (bg,key):continue
        rs2=[r for r,c in cells]; cs2=[c for r,c in cells]
        cr=sum(rs2)/len(rs2); cc=sum(cs2)/len(cs2)
